contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint x) public payable {
        require(x < 1000000 ether);
        uint pbt1 = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        uint pbt2 = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        assert(pbt1 == pbt2 && pbt1 <= block.timestamp + 1 && address(c).balance >= 0 && pbt1 >= 0);
    }
    receive() external payable {}
}

